#include "quake/frame3d.hpp"
#include "quake/generalized_woodbury.hpp"
#include "quake/superlu_solver.hpp"
#include <chrono>
#include <iomanip>
#include <iostream>
using namespace quake;
static CompiledFrame3D model(int stories){Frame3DBuilder b;constexpr double h=3.5;for(int s=0;s<=stories;++s){b.add_node(10*s+1,0,0,s*h,s?1.0:0,s?1.0:0,s?.1:0);if(!s)b.fix(1);}for(int s=1;s<=stories;++s)b.add_elastic_frame(s,10*(s-1)+1,10*s+1,30000,12000,2,.3,.5,.5,1,0,0,15.0*(stories-s+1));b.set_response(10*stories+1,Dof3D::UX);std::vector<int> sn;for(int s=1;s<=stories;++s)sn.push_back(10*s+1);b.set_story_nodes(sn,Dof3D::UX);b.set_updated_pdelta(true);return b.compile();}
int main(int argc,char**argv){int stories=argc>1?std::stoi(argv[1]):20;auto m=model(stories);std::vector<double> u((size_t)m.dof(),0.0);for(int s=1;s<=stories;++s){int ux=m.reduced_dof(10*s+1,Dof3D::UX),uz=m.reduced_dof(10*s+1,Dof3D::UZ);u[(size_t)ux]=.001*s*s;u[(size_t)uz]=-.00005*s;}auto t=m.initial_nonlinear_tangents();auto A=m.effective_initial_matrix(0,0);auto K=m.effective_state_tangent_matrix(u,t,0,0);auto C=m.generalized_state_update_coefficients(u,t);std::vector<double> rhs((size_t)m.dof(),1.0);GeneralizedWoodburySolver w(A,m.generalized_state_update_basis());SuperLUSamePatternSolver d(A);auto t0=std::chrono::steady_clock::now();auto xw=w.solve(rhs,C);double tw=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count();t0=std::chrono::steady_clock::now();auto xd=d.refactor_and_solve(K,rhs);double td=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count();double err=0,den=0;for(size_t i=0;i<xw.size();++i){err=std::max(err,std::abs(xw[i]-xd[i]));den=std::max(den,std::abs(xd[i]));}std::cout<<std::fixed<<std::setprecision(8)<<"stories="<<stories<<" dof="<<m.dof()<<" generalized_basis="<<m.generalized_state_update_basis().cols()<<" active="<<w.last_active_dimension()<<" woodbury="<<tw<<" direct="<<td<<" speedup="<<td/tw<<" relerr="<<err/std::max(1.0,den)<<"\n";}
